/**
 * generated by stackra gen from stackra.config.ts, expo.extend.ts when present (merged last),
 * src/config/{release,theming,i18n,identity,push,telemetry}.config.ts, runway.yaml
 * (telemetry.sentryProject, environments.dev.vars), root runway.yaml (providers.expo,
 * providers.sentry), .stackra/dev/ports.json, assets/public/logo.svg and assets/lang/en/mobile.json
 * — do not edit
 * Purpose: the Expo config: identifiers and store ids (release), icons and splash rasterised from
 *          the logo (theming), the deep-link scheme (release) and universal-link domain (env),
 *          locales (i18n), the config plugins each config-bound package needs, and the fingerprint
 *          runtime policy with the update URL (env).
 * Boundary: public values only; every value here ends up in the binary. Only dev values are
 *           inlined, resolved from `from-member` / `from-port` through `.stackra/dev/ports.json`.
 *           Preview, staging and production values are build-time inputs: runway resolves every
 *           `ref:` and the per-PR origins, syncs them into the EAS environment of the profile
 *           (eas-sync.json), and EAS sets them in `process.env` before this file runs, so no
 *           unresolved placeholder reaches the binary. `expo` from stackra.config.ts is merged
 *           last.
 * Runtime: node
 */
import type { ExpoConfig } from "expo/config";
import { env } from "@stackra/config/env";

/**
 * runway.yaml environments.dev.vars with the cross-member origins resolved from
 * .stackra/dev/ports.json.
 */
const DEV_VARS = {
  EXPO_PUBLIC_EAS_PROJECT_ID: "",
  EXPO_PUBLIC_API_ORIGIN: "http://localhost:4000",
  EXPO_PUBLIC_APP_ORIGIN: "http://localhost:5173",
  EXPO_PUBLIC_REALTIME_ORIGIN: "ws://localhost:4000/realtime",
  EXPO_PUBLIC_ZITADEL_ISSUER: "http://localhost:8080",
  EXPO_PUBLIC_ZITADEL_CLIENT_ID: "mobile-dev",
  EXPO_PUBLIC_SENTRY_DSN: "",
  EXPO_PUBLIC_PUSH_PROVIDER: "expo",
  EXPO_PUBLIC_POSTHOG_KEY: "",
} as const;

const environment = env
  .enum(["dev", "preview", "staging", "production"])
  .default("dev")
  .parse(process.env.STACKRA_ENVIRONMENT);
/**
 * Dev inlines the resolved values; every other environment reads what EAS set from the synced EAS
 * environment.
 */
const vars = environment === "dev" ? DEV_VARS : process.env;
const easProjectId = env
  .str()
  .allowEmpty()
  .parse(vars.EXPO_PUBLIC_EAS_PROJECT_ID ?? "");
const appHost = new URL(env.url().parse(vars.EXPO_PUBLIC_APP_ORIGIN)).host;

const config: ExpoConfig = {
  name: "Stackra", // release.name
  slug: "stackra", // release.slug
  scheme: "stackra", // release.scheme
  version: "0.1.0", // package.json
  orientation: "portrait", // release.orientation
  userInterfaceStyle: "automatic", // theming.schemes includes "system"
  icon: "./icons/app-icon-1024.png", // rasterised from assets/public/logo.svg (theming.logo)
  // i18n.locales → CFBundleLocalizations + InfoPlist strings
  locales: { en: "./locales/en.json", ar: "./locales/ar.json" },
  runtimeVersion: { policy: "fingerprint" }, // release.runtimePolicy
  // env.easProjectId; a bare clone has no update URL
  updates: easProjectId ? { url: `https://u.expo.dev/${easProjectId}` } : { enabled: false },
  // the EXPO_PUBLIC_* values are inlined by Expo from process.env
  extra: { eas: { projectId: easProjectId }, stackra: { environment } },
  ios: {
    supportsTablet: true, // release.ios
    bundleIdentifier: "dev.acme.mobile",
    associatedDomains: [`applinks:${appHost}`], // env.appOrigin
    config: { usesNonExemptEncryption: false },
  },
  android: {
    package: "dev.acme.mobile", // release.android
    predictiveBackGestureEnabled: false,
    adaptiveIcon: {
      foregroundImage: "./icons/adaptive-foreground-1024.png",
      backgroundColor: "#f7f7f5",
    }, // theming.themeColor.light
    intentFilters: [
      {
        action: "VIEW",
        autoVerify: true,
        data: [{ scheme: "https", host: appHost, pathPrefix: "/m" }],
        category: ["BROWSABLE", "DEFAULT"],
      },
    ],
  },
  plugins: [
    "react-native-bottom-tabs", // routes/tabs.layout.ts kind NativeTabs
    "expo-secure-store", // storage drivers (session, secrets)
    "expo-sqlite", // storage drivers (cache, outbox)
    "expo-web-browser", // identity.flow pkce
    [
      "expo-camera",
      { cameraPermission: "Stackra scans product barcodes to add them to an order." },
      // routes/scan.route.ts capability scanner; string from assets/lang/en/mobile.json
      // permissions.camera
    ],
    // push.config.ts; theming.themeColor.dark
    ["expo-notifications", { icon: "./icons/notification-96.png", color: "#1c1e22" }],
    ["expo-updates", { username: "acme" }], // root runway providers.expo.account
    // telemetry.errors.enabled; org from root providers.sentry.org, project from runway.yaml
    // telemetry.sentryProject; DSN is a var; the upload token is a CI secret
    ["@sentry/react-native/expo", { organization: "acme", project: "acme-mobile" }],
    [
      "expo-splash-screen",
      {
        image: "./icons/splash-256.png",
        imageWidth: 96,
        backgroundColor: "#f7f7f5",
        dark: { image: "./icons/splash-dark-256.png", backgroundColor: "#1c1e22" },
      },
    ], // theming.splash
  ],
};

export default config;
